import {MOUNTS} from './companions.mjs?v=0.5';
import {mountAvatar} from './avatar.mjs?v=0.5';
let avatarPreview=null;
import {renderProgression} from './progression-ui.mjs?v=0.5';
import {GRADES} from './economy.mjs?v=0.5';
import {Game,fresh,parseSave,activeQuest,SAVE_KEY,CLASSES,QUESTS,BRANCHES,SPIRITS,RESOURCE_NAMES,NPCS,SHRINES,OBSTACLES,ACHIEVEMENTS,stats,cost,value,questReady,distance} from './engine.mjs?v=0.5';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=fresh(),migration=false,loadWarning='',game,world,keys=new Set(),panel=null,last=0,hudTimer=0,saveTimer=0,active=true,manualAction=null,audioCtx,frames=0,frameClock=0;
try{const raw=localStorage.getItem(SAVE_KEY),legacy=localStorage.getItem('long-mach-v2')||localStorage.getItem('long-mach-v1');if(raw)state=parseSave(raw);else if(legacy){state=parseSave(legacy);migration=true;}}catch(e){loadWarning='Không đọc được bản lưu: '+e.message+' Bản lưu gốc chưa bị thay đổi.';}
game=new Game(state);
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;$('#toasts').append(el);while($('#toasts').children.length>3)$('#toasts').firstChild.remove();setTimeout(()=>el.remove(),4800);}
function save(){if(!game.s.started)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(game.s));$('#saveStatus').textContent='● Đã lưu trên thiết bị';}catch{$('#saveStatus').textContent='⚠ Không lưu được · hãy Xuất lưu';}}
function openModal(html,kind='other',previewState=game.s){const changed=panel!==kind;avatarPreview?.dispose();avatarPreview=null;panel=kind;game.paused=true;keys.clear();$('#modalContent').innerHTML=html;if(changed)$('#modal').scrollTop=0;$('#closeModal').hidden=!game.s.started;if(!$('#modal').open)$('#modal').showModal();if($('#avatarCanvas')){avatarPreview=mountAvatar($('#avatarCanvas'),previewState);$('#avatarLeft').onclick=()=>avatarPreview.rotate(-.45);$('#avatarRight').onclick=()=>avatarPreview.rotate(.45);}}
function closeModal(){if(!game.s.started)return;avatarPreview?.dispose();avatarPreview=null;$('#modal').close();panel=null;game.paused=!active;keys.clear();save();}
$('#closeModal').onclick=closeModal;$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
function sound(kind){if(!game.s.settings.sound)return;try{audioCtx??=new AudioContext();if(audioCtx.state==='suspended')audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.connect(gain);gain.connect(audioCtx.destination);const now=audioCtx.currentTime;osc.type=kind==='hurt'?'sawtooth':'sine';osc.frequency.setValueAtTime(kind==='kill'?650:kind==='heal'?550:kind==='gather'?880:kind==='hurt'?140:300,now);osc.frequency.exponentialRampToValueAtTime(120,now+.15);gain.gain.setValueAtTime(.045,now);gain.gain.exponentialRampToValueAtTime(.001,now+.18);osc.start();osc.stop(now+.19);}catch{}}
function float(e){const p=world.project(e.x,3.5,e.z);if(!p.visible)return;const el=document.createElement('div');el.className='floater '+e.type;el.textContent=e.type==='damage'||e.type==='hurt'?'−'+e.amount:e.type==='heal'?'+'+e.amount:'+1';el.style.left=p.x+'px';el.style.top=p.y+'px';$('#floaters').append(el);setTimeout(()=>el.remove(),1000);}
function events(){for(const e of game.events.splice(0)){if(e.type==='notice')toast(e.text);if(e.type==='level'){toast('Đột phá cấp '+e.level+' · hồi đầy sinh lực và linh lực');save();}if(['damage','hurt','heal','gather'].includes(e.type))float(e);if(['kill','heal','gather','hurt','cast'].includes(e.type))sound(e.type);if(e.type==='mapchange'){const W=world.constructor,angle=world.angle,zoom=world.zoom;world.dispose();world=new W($('#world'),game,$('#labels'));world.angle=angle;world.zoom=zoom;manualAction=null;keys.clear();$('#farmType').options[0].textContent=game.getRegion().mob||'Sói sương';$('#farmType').options[1].textContent=game.getRegion().guard||'Ảnh giáo đồ';save();}if(e.type==='regiondialog'){openModal(`<div class="story"><span class="eyebrow">${esc(e.npc)}</span><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><button class="primary" id="regionClaim">${e.claim?'Nhận thưởng & tiếp tục':'Tiếp tục'}</button></div>`,'story');$('#regionClaim').onclick=()=>{if(!e.claim||game.claimRegion()){closeModal();save();hud();}};}if(e.type==='dialog'){openModal(`<div class="story"><span class="eyebrow">${esc(e.npc)}</span><h2 class="modal-title">${e.claim?QUESTS[game.s.quest].title:'Lời nhắn trên hành trình'}</h2><p>${esc(e.text)}</p>${e.claim?'<button class="primary" id="claim">Nhận thưởng & tiếp tục</button>':'<button class="primary" id="continue">Tiếp tục hành trình</button>'}</div>`,'story');$('#claim')?.addEventListener('click',()=>{if(game.claim()){closeModal();save();hud();}});$('#continue')?.addEventListener('click',closeModal);}if(e.type==='panel')showPanel(e.panel);world.event(e);}}
function startScreen(){let chosen=state.class;openModal(`<div class="prologue"><span class="eyebrow">LONG MẠCH 3D · NĂM MIỀN LONG MẠCH</span><h1>Một lời thề.<br>Một long mạch thức giấc.</h1><p class="lead">Người giữ ấn An Nhiên đã mất tích. Trong màn sương phủ Vân Sơn, một nghi lễ đang hút cạn nguồn sống. Chọn con đường của bạn và lần theo tiếng gọi tới thành Vọng Nguyệt.</p><div class="class-cards">${Object.entries(CLASSES).map(([k,c])=>`<button class="class-card ${chosen===k?'selected':''}" data-class="${k}"><span class="class-icon">${{kiem:'劍',phap:'靈',thuong:'槍'}[k]}</span><h3>${c.name}</h3><small>${c.desc}<br>HP ${c.hp} · Công ${c.atk}</small></button>`).join('')}</div><div class="name-field"><label for="playerName">Tên lữ khách</label><input id="playerName" value="${esc(state.name)}" maxlength="20" autocomplete="off"></div><div class="prologue-footer"><button class="primary" id="startGame">Bước vào Vân Sơn →</button><small>Chơi đơn · Lưu trên thiết bị · Bàn phím & cảm ứng</small></div></div>`,'welcome');$$('[data-class]').forEach(b=>b.onclick=()=>{chosen=b.dataset.class;$$('[data-class]').forEach(x=>x.classList.toggle('selected',x===b));});$('#startGame').onclick=()=>{game.start($('#playerName').value,chosen);world.scene.remove(world.player);world.player=world.human(CLASSES[chosen].color,chosen);world.scene.add(world.player);closeModal();save();hud();};}
const panelNames={loadout:'Trang bị',forge:'Lò rèn',materials:'Nguyên liệu',atlas:'Thế giới',codex:'Bách khoa',equipment:'Tu luyện',inner:'Ba nhánh nội công',skills:'Võ học long mạch',spirits:'Linh thú đồng hành',inventory:'Túi đồ',saves:'Xuất / nhập lưu',journal:'Nhật ký hành trình',settings:'Cài đặt',help:'Phím tắt & điều khiển',map:'Bản đồ long mạch'};
function price(c){return Object.entries(c).map(([k,v])=>`${v} ${RESOURCE_NAMES[k]}`).join(' · ');}
function showPanel(which){
if(which==='bag')which='inventory';if(which==='spirits')which='pets';if(renderProgression(which,{game,openModal,closeModal,showPanel,save,hud}))return;
const s=game.s,st=stats(s);let body='',subtitle='';
if(['equipment','inner','skills'].includes(which)){
 subtitle=which==='equipment'?'Nâng cấp chắc chắn thành công khi đủ tài nguyên. Binh khí, giáp và pháp khí phát triển độc lập.':which==='inner'?'Phân bổ tài nguyên theo lối chơi: chịu đòn, gây sát thương hoặc hồi linh lực.':'Đánh thường không tốn linh lực. Ba kỹ năng và Lướt có hồi chiêu riêng.';
 body='<div class="cards">'+Object.entries(BRANCHES).filter(([,b])=>b.group===which).map(([k,b])=>{let lv=s.upgrades[k],c=cost(s,k),locked=s.quest<b.unlock;return `<article class="upgrade-card"><span class="glyph">${b.icon}</span><h3>${b.name}</h3><span class="eyebrow">BẬC ${lv} / ${b.cap}</span><div class="rank-dots">${Array.from({length:b.cap},(_,i)=>`<i class="${i<lv?'filled':''}"></i>`).join('')}</div><p>${b.desc}</p><small>${locked?'Mở sau nhiệm vụ '+b.unlock:lv===b.cap?'Đã đạt bậc tối đa':price(c)}</small><button data-upgrade="${k}" ${locked||lv>=b.cap||!game.canPay(c)?'disabled':''}>${locked?'Chưa mở khóa':lv>=b.cap?'Đã viên mãn':'Nâng lên bậc '+(lv+1)}</button></article>`;}).join('')+'</div>';
 if(which==='equipment')body+=`<div class="toolbar"><button id="craft" ${!game.canPay({gold:20,herb:2})?'disabled':''}>⚱ Chế bình hồi phục · 20 đồng + 2 linh thảo</button></div><p class="subtext">Hiện có ${s.potions} bình · Uống bằng R · Tự uống dưới 35% HP: ${s.settings.autoPotion?'Bật':'Tắt'}.</p>`;
}
if(which==='spirits'){subtitle='Sau nhiệm vụ 6, Hỏa hồ và Linh lộc được mở khóa. Linh phách nhận khi đánh Ảnh giáo đồ.';body='<div class="cards">'+Object.entries(SPIRITS).map(([k,p])=>{let lv=s.spirits[k],c={gold:100+lv*90,essence:lv+1};return `<article class="upgrade-card"><span class="glyph">${p.icon}</span><h3>${p.name}</h3><span class="eyebrow">${lv?'BẬC '+lv+' / 5':'CHƯA TRIỆU HỒI'}</span><p>${p.desc}</p><small>${s.quest<6?'Mở sau nhiệm vụ 6':lv>=5?'Đã đạt tối đa':price(c)}</small><button data-spirit-up="${k}" ${s.quest<6||lv>=5||!game.canPay(c)?'disabled':''}>${lv?'Nuôi dưỡng':'Triệu hồi'}</button><button class="secondary ${s.spirit===k&&lv?'active':''}" data-spirit="${k}" ${!lv?'disabled':''}>${s.spirit===k&&lv?'Đang đồng hành':'Chọn đồng hành'}</button></article>`;}).join('')+'</div><p class="subtext">Thú cưỡi Linh lộc tăng tốc độ di chuyển, tự xuống khi chiến đấu. Nhấn V để lên hoặc xuống.</p>';}
if(which==='saves'){subtitle='Nguyên liệu được giữ khi hồi sinh. Chuyển thiết bị bằng Xuất lưu / Nhập lưu.';body='<div class="inventory">'+[['gold','◈','Đồng'],['ore','◆','Thanh Thạch'],['herb','❧','Linh thảo'],['energy','✧','Linh khí'],['essence','◉','Linh phách'],['potions','⚱','Bình hồi phục']].map(([k,i,n])=>`<div class="item"><span>${i}</span><div><strong>${s[k]}</strong><small>${n}</small></div></div>`).join('')+'</div><div class="toolbar"><button id="exportSave">Xuất lưu JSON</button><button id="importSave">Nhập bản lưu 2D / 3D</button><button id="openCraft">Mở chế tạo thuốc</button></div>';}
if(which==='journal'){subtitle='Mỗi nhiệm vụ có thể nhận thưởng một lần. Truy nã nhận thưởng mỗi 10 quái thường.';let total=s.counts.wolves+s.counts.cultists;body=`<div class="toolbar"><button id="bounty" ${Math.floor(total/10)<=s.bounties?'disabled':''}>Truy nã · ${Math.max(0,total-s.bounties*10)} / 10 quái · Nhận 120 đồng + 2 đá</button></div><h3>Thành tựu</h3><div class="journal-list">${ACHIEVEMENTS.map((a,i)=>`<div class="journal-row"><h3>${a.title}</h3><p>${Math.min(value(s,a.key),a.need)} / ${a.need} · ${a.gold} đồng</p><button data-achievement="${i}" ${s.achievements.includes(i)||value(s,a.key)<a.need?'disabled':''}>${s.achievements.includes(i)?'Đã nhận':'Nhận thưởng'}</button></div>`).join('')}</div><h3>Chính tuyến</h3><div class="journal-list">${QUESTS.map((q,i)=>`<div class="journal-row ${i<s.quest?'complete':i===s.quest?'current':''}"><h3>${i<s.quest?'✓':String(i+1).padStart(2,'0')} · ${q.title}</h3><p>Chương ${q.chapter} · ${q.text}</p><small>${i<s.quest?'Đã hoàn thành':i===s.quest?'Đang thực hiện':'Chưa mở'}</small></div>`).join('')}</div>`;}
if(which==='settings'){subtitle='Game tạm dừng khi mở cửa sổ hoặc chuyển sang tab khác. Auto không chạy khi đóng trình duyệt.';body=`<div class="settings-list"><label>Tự uống thuốc dưới 35% HP <input id="autoPotionSetting" type="checkbox" ${s.settings.autoPotion?'checked':''}></label><label>Âm thanh hiệu ứng <input id="soundSetting" type="checkbox" ${s.settings.sound?'checked':''}></label><label>Chất lượng 3D <select id="qualitySetting"><option value="high" ${s.settings.quality==='high'?'selected':''}>Cao · bóng đổ</option><option value="low" ${s.settings.quality==='low'?'selected':''}>Nhẹ · tiết kiệm GPU</option></select></label><label>Khoảng cách camera <input id="cameraZoom" type="range" min="20" max="55" value="${world.zoom}"></label></div><div class="toolbar"><button id="exportSave">Xuất lưu</button><button id="importSave">Nhập lưu</button><button id="showHelp">Phím tắt</button><button id="resetGame">Bắt đầu lại</button></div><p class="subtext">Bản 0.5 · WebGL 3D · Chơi đơn. Tiến trình lưu riêng theo trình duyệt và địa chỉ game. Bản lưu 2D cũ được giữ tại khóa gốc.</p>`;}
if(which==='help'){subtitle='Nhập bằng bàn phím hoặc các nút trên màn hình. Khi gõ tên nhân vật, phím tắt không kích hoạt.';const entries=[['W A S D / ↑↓←→','Di chuyển theo hướng camera; tự dừng auto'],['Chạm / nhấp mặt đất','Đi đến vị trí; nhấp quái để chọn và tấn công'],['Kéo trên bản đồ 3D','Xoay camera; lăn chuột để zoom'],['1 / Space','Đánh thường'],['2 / Q','Long trảm — tốn 18 linh lực'],['3','Địa chấn — tốn 30 linh lực, gây choáng'],['4','Hồi nguyên — tốn 25 linh lực'],['Shift','Lướt, né đòn trong thời gian ngắn'],['E / R / V','Tương tác / uống thuốc / thú cưỡi'],['F / G / T','Auto farm / auto đào khoáng / auto nhiệm vụ'],['Esc','Đóng cửa sổ hoặc dừng auto'],['Tab','Đổi mục tiêu gần nhất'],['C / K / L / P','Trang bị / nội công / kỹ năng / linh thú'],['B / J / M / O','Túi đồ / nhật ký / bản đồ / cài đặt'],['I / N / U','Lò rèn / thế giới & chuyển map / thú cưỡi'],['Z / X / H','Xoay camera trái / phải / đi về làng'],['?','Mở bảng phím tắt']];body='<table class="key-table">'+entries.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')+'</table><p class="subtext">Auto nhiệm vụ di chuyển, đánh quái và thu thập theo mục tiêu. Hội thoại, nhận thưởng và dùng tài nguyên nâng cấp vẫn cần bạn chọn. Auto dừng sau khi gục ngã.</p>';}
if(which==='map'){subtitle='Nhấp một điểm trên bản đồ để di chuyển. Chạm lại nút M để đóng.';body='<canvas id="bigMap" class="big-map" width="900" height="700" aria-label="Bản đồ tương tác"></canvas><div class="map-legend"><span>● Bạn</span><span>● NPC</span><span>◆ Khoáng</span><span>● Thảo dược</span><span>● Linh khí</span><span>● Quái / boss</span></div>';}
openModal(`<span class="eyebrow">${esc(s.name)} · ${CLASSES[s.class].name} · CẤP ${s.level}</span><h2 class="modal-title">${panelNames[which]}</h2><div class="panel-stats"><span>◈ ${s.gold} đồng</span><span>◆ ${s.ore} đá</span><span>❧ ${s.herb} thảo</span><span>✧ ${s.energy} khí</span><span>Công ${st.atk} · Thủ ${st.def} · HP ${st.hp}</span></div><div class="panel-tabs">${Object.entries(panelNames).filter(([k])=>!['settings','help','map'].includes(k)).map(([k,n])=>`<button data-nav="${k}" class="${k===which?'active':''}">${n}</button>`).join('')}</div><p class="subtext">${subtitle}</p>${body}`,which);
$$('[data-nav]').forEach(b=>b.onclick=()=>showPanel(b.dataset.nav));$$('[data-upgrade]').forEach(b=>b.onclick=()=>{game.upgrade(b.dataset.upgrade);save();showPanel(which);hud();});$('#craft')?.addEventListener('click',()=>{game.craft();save();showPanel(which);});$$('[data-spirit-up]').forEach(b=>b.onclick=()=>{game.spiritUpgrade(b.dataset.spiritUp);save();showPanel(which);});$$('[data-spirit]').forEach(b=>b.onclick=()=>{game.selectSpirit(b.dataset.spirit);save();showPanel(which);});$('#bounty')?.addEventListener('click',()=>{game.bounty();save();showPanel(which);});$$('[data-achievement]').forEach(b=>b.onclick=()=>{game.achievement(+b.dataset.achievement);save();showPanel(which);});$('#openCraft')?.addEventListener('click',()=>showPanel('equipment'));$('#exportSave')?.addEventListener('click',exportSave);$('#importSave')?.addEventListener('click',()=>$('#importInput').click());$('#showHelp')?.addEventListener('click',()=>showPanel('help'));$('#resetGame')?.addEventListener('click',confirmReset);
$('#autoPotionSetting')?.addEventListener('change',e=>{s.settings.autoPotion=e.target.checked;save();});$('#soundSetting')?.addEventListener('change',e=>{s.settings.sound=e.target.checked;sound('heal');save();});$('#qualitySetting')?.addEventListener('change',e=>{s.settings.quality=e.target.value;world.quality(e.target.value);save();});$('#cameraZoom')?.addEventListener('input',e=>world.zoom=+e.target.value);
if(which==='map'){drawMap($('#bigMap'));$('#bigMap').onclick=e=>{const r=e.target.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*180,z=(e.clientY-r.top)/r.height*140;closeModal();game.goto(x,z);};}
}
function exportSave(){const blob=new Blob([JSON.stringify(game.s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='long-mach-3d-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function confirmReset(){openModal('<div class="story"><span class="eyebrow">HÀNH TRÌNH MỚI</span><h2 class="modal-title">Bắt đầu lại từ Vân Sơn?</h2><p>Tiến trình 3D hiện tại sẽ được thay thế. Hãy xuất bản lưu nếu muốn quay lại nhân vật này.</p><div class="toolbar"><button id="backupBeforeReset">Xuất bản lưu hiện tại</button><button class="primary" id="confirmReset">Bắt đầu lại</button></div></div>','reset');$('#backupBeforeReset').onclick=exportSave;$('#confirmReset').onclick=()=>{try{localStorage.setItem(SAVE_KEY+'-backup',JSON.stringify(game.s));localStorage.setItem(SAVE_KEY,JSON.stringify(fresh()));location.reload();}catch{toast('Không ghi được bản lưu. Chưa xóa tiến trình.');}};}
$('#importInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error('Tệp quá lớn.');const raw=await f.text(),next=parseSave(raw);openModal(`<div class="story"><span class="eyebrow">KHÔI PHỤC HÀNH TRÌNH</span><h2 class="modal-title">${esc(next.name)} · Cấp ${next.level}</h2><p>Nhân vật này sẽ thay thế tiến trình hiện tại. Một bản sao tiến trình đang chơi sẽ được giữ trong bộ nhớ trình duyệt.</p><button class="primary" id="confirmImport">Khôi phục bản lưu</button></div>`,'import');$('#confirmImport').onclick=()=>{try{localStorage.setItem(SAVE_KEY+'-backup',JSON.stringify(game.s));localStorage.setItem(SAVE_KEY,JSON.stringify(next));location.reload();}catch{toast('Không ghi được bản lưu. Tiến trình chưa bị thay thế.');}};}catch(err){toast('Không nhập được: '+err.message);}e.target.value='';};
function drawMap(c){const cx=c.getContext('2d'),w=c.width,h=c.height,sx=w/180,sz=h/140;cx.clearRect(0,0,w,h);cx.fillStyle='#'+game.getRegion().ground.toString(16).padStart(6,'0');cx.fillRect(0,0,w,h);cx.strokeStyle='#75908055';cx.lineWidth=1;for(let i=0;i<=180;i+=20){cx.beginPath();cx.moveTo(i*sx,0);cx.lineTo(i*sx,h);cx.stroke();}for(let i=0;i<=140;i+=20){cx.beginPath();cx.moveTo(0,i*sz);cx.lineTo(w,i*sz);cx.stroke();}if(['van','bang'].includes(game.s.map)){cx.fillStyle='#407979';cx.beginPath();cx.ellipse(23*sx,28*sz,15*sx,15*sz,0,0,Math.PI*2);cx.fill();}cx.strokeStyle='#b5b18a88';cx.lineWidth=w>300?10:3;cx.beginPath();[[32,120],[32,97],[67,84],[107,35],[130,44],[159,23]].forEach(([x,z],i)=>i?cx.lineTo(x*sx,z*sz):cx.moveTo(x*sx,z*sz));cx.stroke();function dot(x,z,col,r=2){cx.fillStyle=col;cx.beginPath();cx.arc(x*sx,z*sz,r*(w>300?2.4:1),0,Math.PI*2);cx.fill();}for(const n of game.nodes)if(!n.cd)dot(n.x,n.z,GRADES[n.grade].hex);for(const n of game.enemies)if(!n.dead)dot(n.x,n.z,n.boss?'#e69572':'#bd776e',n.boss?3:1.4);for(const n of game.npcs)dot(n.x,n.z,'#efd297',3);for(const n of game.shrines)dot(n.x,n.z,game.s.seals.includes(n.id)?'#b7d58c':'#c0ace0',2.5);if(game.path.length){cx.strokeStyle='#f3e3aa';cx.lineWidth=1;cx.beginPath();cx.moveTo(game.s.x*sx,game.s.z*sz);game.path.forEach(p=>cx.lineTo(p.x*sx,p.z*sz));cx.stroke();}dot(game.s.x,game.s.z,'#fff9d9',3);cx.strokeStyle='#fff9d970';cx.lineWidth=1;cx.beginPath();cx.arc(game.s.x*sx,game.s.z*sz,w>300?17:7,0,Math.PI*2);cx.stroke();dot(game.getRegion().portal.x,game.getRegion().portal.z,'#e9b4ff',4);if(w>300){cx.font='18px Segoe UI';cx.textAlign='center';cx.fillStyle='#e4d5b3';cx.fillText(game.getRegion().name.toUpperCase(),90*sx,10*sz);cx.fillText('CỔNG',37*sx,132*sz);}}

function hud(){const s=game.s,st=stats(s),q=activeQuest(s);s.hp=Math.min(s.hp,st.hp);s.mp=Math.min(s.mp,st.mp);$('#name').textContent=s.name;$('#classLevel').textContent=CLASSES[s.class].name+' · '+s.level;$('#hpFill').style.width=Math.max(0,s.hp/st.hp*100)+'%';$('#mpFill').style.width=s.mp/st.mp*100+'%';$('#hpText').textContent=Math.ceil(s.hp)+' / '+st.hp;$('#mpText').textContent=Math.floor(s.mp)+' / '+st.mp;$('#power').textContent='Công '+st.atk+' · Thủ '+st.def+' · EXP '+s.xp+'/'+s.level*100;$('#expFill').style.width=Math.min(100,s.xp/(s.level*100)*100)+'%';for(const k of ['gold','ore','energy'])$('#'+k).textContent=s[k].toLocaleString('vi-VN');$('#potionCount').textContent='Thuốc · '+s.potions;$('#mount').classList.toggle('active',game.mount);
$('#farmType').options[0].textContent=game.getRegion().mob||'Sói sương';$('#farmType').options[1].textContent=game.getRegion().guard||'Ảnh giáo đồ';$('#questCount').textContent=Math.min((s.map==='van'?s.quest:s.regions[s.map].quest)+1,s.map==='van'?12:4).toString().padStart(2,'0')+' / '+(s.map==='van'?12:4);$('#questTitle').textContent=q?.title||'Đã hoàn thành '+game.getRegion().name;$('#questDescription').textContent=q?.text||'Mở Thế giới để chọn khu vực tiếp theo, săn quái và hoàn thiện trang bị.';$('#questGoals').innerHTML=q?q.goals.map(g=>`<div class="goal ${value(s,g.key)>=g.need?'done':''}"><span>${g.label}</span><b>${Math.min(value(s,g.key),g.need)} / ${g.need}</b></div>`).join(''):'';$('#questReward').textContent=q?'Thưởng '+q.gold+' đồng · '+q.xp+' EXP':'Khu vực đã bình yên';$('#track').textContent=questReady(s)?'⌖ Về trả nhiệm vụ':'⌖ Chỉ đường';$('#track').disabled=!q;$('#autoQuest').disabled=!q;$('#autoQuest').classList.toggle('active',game.mode==='quest');$('#autoFarm').classList.toggle('active',game.mode==='farm');$$('[data-auto]').forEach(b=>b.classList.toggle('active',game.mode===b.dataset.auto));$('#autoStatus').textContent={off:'ĐIỀU KHIỂN THỦ CÔNG',farm:'AUTO FARM · '+(game.farmType==='wolf'?(game.getRegion().mob||'SÓI SƯƠNG'):(game.getRegion().guard||'ẢNH GIÁO ĐỒ')),ore:'ĐANG TỰ ĐỘNG ĐÀO KHOÁNG',herb:'ĐANG TỰ ĐỘNG HÁI THUỐC',energy:'ĐANG TỰ ĐỘNG HẤP THU',quest:'ĐANG THEO NHIỆM VỤ'}[game.mode];$('.auto-status').classList.toggle('running',game.mode!=='off');$('#stopAuto').hidden=game.mode==='off';
$('#mount span').textContent=(game.mount?'Xuống ':'')+MOUNTS[s.companions.mount].name;$$('[data-skill]').forEach(b=>{const cd=game.cooldowns[b.dataset.skill];b.querySelector('b').textContent=cd>.1?Math.ceil(cd):'';b.setAttribute('aria-label',b.querySelector('span').textContent+(cd>.1?' · hồi '+Math.ceil(cd)+' giây':''));});
let region=s.map!=='van'?game.getRegion().name:s.x>122?'Vọng Nguyệt':s.z<55?'Cổ đàn Thiên Ấn':s.x>58?'Rừng Sương':'Vân Sơn';$('#region').textContent=region;$('#regionSubtitle').textContent=game.getRegion().subtitle;
const e=game.enemies.find(e=>e.id===game.selected&&!e.dead);$('#targetCard').hidden=!e;if(e){$('#targetName').textContent=e.name;$('#targetHP').style.width=Math.max(0,e.hp/e.max*100)+'%';$('#targetHealth').textContent=Math.max(0,Math.ceil(e.hp))+' / '+e.max+(game.unlocked(e)?'':' · Cần giải 3 phong ấn');}
const near=(distance(s,game.getRegion().portal)<6?{name:'Cổng dịch chuyển · Thế giới [N]'}:null)||game.npcs.find(n=>distance(s,n)<5.5)||game.nodes.find(n=>!n.cd&&distance(s,n)<4)||game.shrines.find(n=>!s.seals.includes(n.id)&&distance(s,n)<4);$('#interaction').hidden=!near&&!game.channel;if(near)$('#interactionText').textContent=near.name||({ore:'Thanh Thạch',herb:'Linh thảo',energy:'Linh khí'}[near.type])||'Trụ phong ấn';if(game.channel){$('#interactionText').textContent=game.channel.type==='seal'?'Đang giải phong ấn…':'Đang thu thập…';$('#channel').style.display='block';$('#channelFill').style.width=(1-game.channel.time/game.channel.total)*100+'%';}else $('#channel').style.display='none';$('#coordinates').textContent=Math.round(s.x)+' · '+Math.round(s.z);drawMap($('#minimap'));}
function mode(m){if(!game.s.started||game.paused)return;manualAction=null;game.setMode(m);hud();}
function track(){const s=game.s,q=activeQuest(s);if(!q)return;if(s.map!=='van'){if(q.goals.some(g=>g.key==='regionalCraft'&&value(s,g.key)<g.need))return showPanel('forge');game.setMode('quest');return;}let p;if(questReady(s)||q.goals[0]?.key==='talk')p=game.npcs.find(n=>n.id===q.npc);else{let goal=q.goals.find(g=>value(s,g.key)<g.need),k=goal.key;if(['wolves','cultists','guardian','lord'].includes(k))p=game.nearest(game.enemies.filter(e=>!e.dead&&e.type===({wolves:'wolf',cultists:'cultist',guardian:'guardian',lord:'lord'}[k])));else if(['mined','gathered','meditated'].includes(k))p=game.nearest(game.nodes.filter(n=>!n.cd&&n.type===({mined:'ore',gathered:'herb',meditated:'energy'}[k])));else if(k==='seals')p=game.shrines.find(n=>!s.seals.includes(n.id));else return showPanel(k==='spiritLevel'?'spirits':k==='inner'?'inner':'equipment');}if(p){game.goto(p.x,p.z+1.5);toast('Đang đi đến mục tiêu. Nhấn E khi đến gần.');}}
function selectTarget(){const es=game.enemies.filter(e=>!e.dead&&distance(game.s,e)<28).sort((a,b)=>distance(game.s,a)-distance(game.s,b));if(!es.length)return;let i=es.findIndex(e=>e.id===game.selected);game.selected=es[(i+1)%es.length].id;hud();}
$$('[data-panel]').forEach(b=>b.onclick=()=>showPanel(b.dataset.panel));$('#characterButton').onclick=()=>showPanel('loadout');$('#settings').onclick=()=>showPanel('settings');$('#help').onclick=()=>showPanel('help');$('#mapButton').onclick=()=>showPanel('map');$('#track').onclick=track;$('#autoQuest').onclick=()=>mode('quest');$('#toggleQuest').onclick=()=>$('#tracker').classList.toggle('collapsed');$('#autoFarm').onclick=()=>mode('farm');$('#gatherGrade').value=game.s.gatherGrade;$('#gatherGrade').onchange=e=>{game.s.gatherGrade=+e.target.value;game.path=[];game.channel=null;save();};$('#farmType').onchange=e=>{game.farmType=e.target.value;game.path=[];game.destination=null;hud();};$$('[data-auto]').forEach(b=>b.onclick=()=>mode(b.dataset.auto));$('#stopAuto').onclick=()=>{game.stop();hud();};$$('[data-skill]').forEach(b=>b.onclick=()=>game.attack(b.dataset.skill));$('#potion').onclick=()=>{if(!game.potion())toast(game.s.potions?'Sinh lực đang đầy.':'Hết thuốc. Chế thêm trong Trang bị.');hud();};$('#interact').onclick=()=>game.interact();$('#mount').onclick=()=>game.toggleMount();$('#rotateLeft').onclick=()=>world.rotate(-.25);$('#rotateRight').onclick=()=>world.rotate(.25);$('#zoomIn').onclick=()=>world.zoom=Math.max(20,world.zoom-3);$('#zoomOut').onclick=()=>world.zoom=Math.min(55,world.zoom+3);$('#home').onclick=()=>{game.goto(32,97);toast('Đang đi về tiền trạm khu vực.');};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Trình duyệt này không hỗ trợ toàn màn hình.');}};
const actionMap={Digit1:()=>game.attack(),Space:()=>game.attack(),Digit2:()=>game.attack('slash'),KeyQ:()=>game.attack('slash'),Digit3:()=>game.attack('nova'),Digit4:()=>game.attack('mend'),ShiftLeft:()=>game.attack('dash'),ShiftRight:()=>game.attack('dash'),KeyE:()=>game.interact(),KeyR:()=>game.potion(),KeyV:()=>game.toggleMount(),KeyF:()=>mode('farm'),KeyG:()=>mode('ore'),KeyT:()=>mode('quest'),KeyC:()=>showPanel('loadout'),KeyI:()=>showPanel('forge'),KeyN:()=>showPanel('atlas'),KeyK:()=>showPanel('inner'),KeyL:()=>showPanel('skills'),KeyU:()=>showPanel('mounts'),KeyP:()=>showPanel('pets'),KeyB:()=>showPanel('inventory'),KeyJ:()=>showPanel('journal'),KeyM:()=>showPanel('map'),KeyO:()=>showPanel('settings'),KeyH:()=>game.goto(32,97),KeyZ:()=>world.rotate(-.2),KeyX:()=>world.rotate(.2),Tab:selectTarget};
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if($('#modal').open){if(e.code==='Escape')closeModal();return;}if(['Tab','Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'){game.stop();manualAction=null;hud();return;}if(!game.s.started)return;keys.add(e.code);if(e.key==='?'){showPanel('help');return;}if(!e.repeat)actionMap[e.code]?.();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
$$('[data-move]').forEach(b=>{const k={up:'KeyW',left:'KeyA',down:'KeyS',right:'KeyD'}[b.dataset.move];b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(k);};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>keys.delete(k);});
let pointerStart=null;$('#world').oncontextmenu=e=>e.preventDefault();$('#world').onpointerdown=e=>{if(!game.s.started||game.paused)return;pointerStart={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,drag:false,id:e.pointerId};e.target.setPointerCapture(e.pointerId);};$('#world').onpointermove=e=>{if(!pointerStart||pointerStart.id!==e.pointerId)return;if(Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>8)pointerStart.drag=true;if(pointerStart.drag){world.rotate(-(e.clientX-pointerStart.lastX)*.006);world.pitch=Math.max(.4,Math.min(1.05,world.pitch+(e.clientY-pointerStart.lastY)*.003));}pointerStart.lastX=e.clientX;pointerStart.lastY=e.clientY;};$('#world').onpointercancel=()=>pointerStart=null;$('#world').onpointerup=e=>{if(!pointerStart)return;const drag=pointerStart.drag;pointerStart=null;if(drag)return;const p=world.pick(e.clientX,e.clientY);if(!p)return;let en=game.nearest(game.enemies.filter(e=>!e.dead&&distance(p,e)<3));if(en){game.stop(true);game.selected=en.id;if(!game.unlocked(en))return toast('Giải ba phong ấn trước khi thách đấu Chủ tế.');if(distance(game.s,en)<=stats(game.s).range)game.attack();else{game.navigate(en.x,en.z);manualAction={type:'attack',id:en.id};}return;}let n=game.npcs.find(n=>distance(p,n)<3)||game.nodes.find(n=>!n.cd&&distance(p,n)<2.5);game.goto(p.x,p.z);manualAction=n?{type:'interact',id:n.id}:null;};$('#world').addEventListener('wheel',e=>{e.preventDefault();if(world)world.zoom=Math.max(20,Math.min(55,world.zoom+e.deltaY*.025));},{passive:false});
document.addEventListener('visibilitychange',()=>{active=!document.hidden;game.paused=!active||$('#modal').open;$('#pauseBadge').hidden=active;keys.clear();last=0;if(!active)save();});window.addEventListener('beforeunload',save);
$('#world').addEventListener('webglcontextlost',e=>{e.preventDefault();game.paused=true;save();$('#boot').hidden=false;$('#boot').innerHTML='<div class="fallback"><h2>Kết nối đồ họa bị gián đoạn</h2><p>Tiến trình đã được lưu nếu bộ nhớ trình duyệt khả dụng. Tải lại game để khôi phục.</p><button onclick="location.reload()">Tải lại</button></div>';});
function frame(t){let dt=last?Math.min((t-last)/1000,.08):0;last=t;if(active){let right=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),forward=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0);if(right||forward)manualAction=null;const a=world.angle;game.update(dt,{x:right*Math.cos(a)-forward*Math.sin(a),z:-right*Math.sin(a)-forward*Math.cos(a)});if(!game.paused&&(keys.has('Space')||keys.has('Digit1')))game.attack();if(manualAction&&!game.paused){let obj=manualAction.type==='attack'?game.enemies.find(e=>e.id===manualAction.id):game.npcs.find(n=>n.id===manualAction.id)||game.nodes.find(n=>n.id===manualAction.id);if(obj&&distance(game.s,obj)<(manualAction.type==='attack'?stats(game.s).range:4)){game.path=[];game.destination=null;if(manualAction.type==='attack')game.attack();else game.interact(obj.id);manualAction=null;}}if(!avatarPreview)world.update(dt);events();hudTimer+=dt;saveTimer+=dt;frames++;frameClock+=dt;if(hudTimer>.15){hudTimer=0;hud();}if(saveTimer>4){saveTimer=0;save();}if(frameClock>2){$('#fps').textContent='3D · '+Math.round(frames/frameClock)+' FPS · Chơi đơn';frames=0;frameClock=0;}}requestAnimationFrame(frame);}
try{const {World}=await import('./scene.mjs?v=0.5');world=new World($('#world'),game,$('#labels'));$('#boot').hidden=true;hud();requestAnimationFrame(frame);if(!state.started)startScreen();if(migration){save();toast('Đã chuyển tiến trình cũ sang bản 0.3. Bản lưu gốc vẫn được giữ.');}if(loadWarning)toast(loadWarning);}catch(error){console.error('3D initialization failed',error);$('#boot').innerHTML='<div class="fallback"><span class="eyebrow">LONG MẠCH 3D</span><h2>Chưa khởi tạo được đồ họa 3D</h2><p>Game cần WebGL 2. Hãy mở bằng trình duyệt có tăng tốc phần cứng. Nếu chạy trên máy tính từ mã nguồn, dùng CHOI-GAME.cmd thay vì mở trực tiếp file HTML.</p><p>Bản lưu chưa bị thay đổi.</p><button id="retry">Thử tải lại</button></div>';$('#retry').onclick=()=>location.reload();}

